//! Sony ARW 6 "Compressed RAW 2" (TIFF compression 32766; ILCE-7M5
//! Compressed and Compressed HQ): per tile a 5/3 wavelet of a green plane
//! and red/blue residuals, entropy-coded in packets, decoded to 12-bit codes
//! and expanded through a fixed curve to linear values (black 1024, white
//! 32800, as Adobe DNG Converter writes them).

use rayon::prelude::*;

use crate::pixarray::PixU16;

type Res<T> = std::result::Result<T, String>;

const STREAM_OFFSET: u32 = 0x200;
const INTERNAL_BIAS: i32 = 2048;
const MAX_PLANE_SAMPLES: u64 = 128 * 1024 * 1024;

/// Black and white level of the decoded data.
pub const SONY_ARW6_BLACK: u16 = 1024;
pub const SONY_ARW6_WHITE: u16 = 32800;

fn require(cond: bool) -> Res<()> {
  if cond { Ok(()) } else { Err("ARW6: corrupt data".to_string()) }
}

fn align_up(value: i32, multiple: i32) -> i32 {
  ((value + multiple - 1) / multiple) * multiple
}

fn be16(p: &[u8], at: usize) -> u16 {
  u16::from_be_bytes([p[at], p[at + 1]])
}

fn be32(p: &[u8], at: usize) -> u32 {
  u32::from_be_bytes([p[at], p[at + 1], p[at + 2], p[at + 3]])
}

fn le32(p: &[u8], at: usize) -> u32 {
  u32::from_le_bytes([p[at], p[at + 1], p[at + 2], p[at + 3]])
}

fn floor_shift(x: i64, bits: i32) -> i32 {
  if bits <= 0 {
    return x as i32;
  }
  let d = 1i64 << bits;
  (if x >= 0 { x >> bits } else { -(((-x) + d - 1) >> bits) }) as i32
}

fn sign16(x: i32) -> i32 {
  let x = x & 0xffff;
  if x >= 0x8000 { x - 0x10000 } else { x }
}

fn edge_detail(x: i32, odd_mode: bool) -> i32 {
  let signed_half_step = x.signum();
  let is_odd = x % 2 != 0;
  let use_half_step = if odd_mode { is_odd } else { x != 0 && !is_odd };
  2 * x + if use_half_step { signed_half_step } else { 0 }
}

