fn lut_value(code: i32) -> u16 {
  LLVC3_CURVE[code.clamp(0, 4095) as usize]
}

#[derive(Clone, Default)]
struct Plane {
  rows: i32,
  cols: i32,
  data: Vec<i32>,
}

impl Plane {
  fn new(rows: i32, cols: i32) -> Res<Self> {
    require(rows >= 0 && cols >= 0)?;
    let samples = rows as u64 * cols as u64;
    require(samples <= MAX_PLANE_SAMPLES)?;
    Ok(Self {
      rows,
      cols,
      data: vec![0; samples as usize],
    })
  }

  #[inline]
  fn at(&self, r: i32, c: i32) -> i32 {
    self.data[r as usize * self.cols as usize + c as usize]
  }

  #[inline]
  fn set(&mut self, r: i32, c: i32, v: i32) {
    let cols = self.cols as usize;
    self.data[r as usize * cols + c as usize] = v;
  }

  fn row(&self, r: i32) -> &[i32] {
    let cols = self.cols as usize;
    &self.data[r as usize * cols..(r as usize + 1) * cols]
  }

  fn row_mut(&mut self, r: i32) -> &mut [i32] {
    let cols = self.cols as usize;
    &mut self.data[r as usize * cols..(r as usize + 1) * cols]
  }
}

#[derive(Clone, Copy)]
struct DirectoryEntry {
  group: i32,
  index: i32,
  start: u32,
  length: u32,
}

#[derive(Clone, Copy, Default)]
struct StreamInfo {
  offset: u32,
  length: u32,
  tile_x: i32,
  tile_y: i32,
  tile_w: i32,
  tile_h: i32,
  coded_width: i32,
  logical_height: i32,
}

#[derive(Clone, Copy)]
struct PacketRecord {
  byte_length: u32,
  selectors: [u8; 3],
  payload_offset: u32,
}

struct Packet<'a> {
  kind: i32,
  block_count: i32,
  data: &'a [u8],
  records: Vec<PacketRecord>,
}

fn stream_payload_length(stream: &[u8]) -> Res<u32> {
  require(stream.len() >= 0x80)?;
  let mut payload: u64 = 0;
  for off in [0, 3, 6, 9, 12] {
    payload += ((be32(stream, 0x10 + off) >> 4) & 0x0fff_fff0) as u64;
  }
  require(payload <= stream.len() as u64 - 0x80)?;
  Ok(0x80 + payload as u32)
}

fn parse_stream_header(stream: &[u8]) -> Option<StreamInfo> {
  if stream.len() < 0x80 || (&stream[..4] != b"A000" && &stream[..4] != b"0000") {
    return None;
  }
  let word_c = be16(stream, 0x0c);
  let word_e = be16(stream, 0x0e);
  let decoded_bits = (word_c >> 4) & 0x3f;
  let components = word_e >> 13;
  let mode = (word_e >> 10) & 0x03;
  if decoded_bits != 16 || components != 3 || mode != 3 {
    return None;
  }
  let coded_width = be16(stream, 8) as i32;
  let coded_half_height = be16(stream, 0x0a) as i32;
  if coded_width <= 0 || coded_half_height <= 0 || coded_width & 15 != 0 {
    return None;
  }
  Some(StreamInfo {
    coded_width,
    logical_height: coded_half_height * 2,
    ..Default::default()
  })
}

fn find_streams(strip: &[u8], full_width: i32, full_height: i32) -> Vec<StreamInfo> {
  let mut streams = Vec::new();
  if full_width <= 0 || full_height <= 0 {
    return streams;
  }
  let strip_size = strip.len() as u32;
  if strip_size < STREAM_OFFSET + 0x80 {
    return streams;
  }
  let count = le32(strip, 0);
  if (1..=16).contains(&count) {
    for index in 0..count {
      let entry = 0x08 + index * 0x18;
      if entry + 0x18 > strip_size {
        streams.clear();
        break;
      }
      let e = entry as usize;
      let table_offset = le32(strip, e);
      let tile_x = le32(strip, e + 0x08) as i32;
      let tile_y = le32(strip, e + 0x0c) as i32;
      let entry_tile_w = le32(strip, e + 0x10) as i32;
      let entry_tile_h = le32(strip, e + 0x14) as i32;
      let start = if table_offset != 0 { table_offset } else { STREAM_OFFSET };
      if start > strip_size - 0x80 {
        streams.clear();
        break;
      }
      let search_end = (strip_size - 0x80).min(start.saturating_add(0x1000));
      let mut found = false;
      let mut candidate = start;
      while candidate <= search_end {
        let rest = &strip[candidate as usize..];
        if let (Some(mut info), Ok(length)) = (parse_stream_header(rest), stream_payload_length(rest)) {
          if length > 0x80 && candidate as u64 + length as u64 <= strip_size as u64 {
            info.offset = candidate;
            info.length = length;
            info.tile_x = tile_x;
            info.tile_y = tile_y;
            info.tile_w = if entry_tile_w != 0 { entry_tile_w } else { info.coded_width };
            info.tile_h = if entry_tile_h != 0 { entry_tile_h } else { info.logical_height };
            let fits = info.tile_x >= 0
              && info.tile_y >= 0
              && info.tile_w == info.coded_width
              && info.tile_h == info.logical_height
              && info.tile_x <= full_width - info.tile_w
              && info.tile_y <= full_height - info.tile_h;
            if fits {
              streams.push(info);
              found = true;
              break;
            }
          }
        }
        candidate += 0x10;
      }
      if !found {
        streams.clear();
        break;
      }
    }
    if streams.len() == count as usize {
      return streams;
    }
  }
  streams.clear();
  let rest = &strip[STREAM_OFFSET as usize..];
  if let (Some(mut info), Ok(length)) = (parse_stream_header(rest), stream_payload_length(rest)) {
    info.offset = STREAM_OFFSET;
    info.length = length;
    info.tile_w = info.coded_width;
    info.tile_h = info.logical_height;
    if info.coded_width == full_width && info.logical_height == full_height {
      streams.push(info);
    }
  }
  streams
}

struct HeaderBits<'a> {
  data: &'a [u8],
  bitpos: u64,
}

impl HeaderBits<'_> {
  fn read(&mut self, nbits: u32) -> Res<u32> {
    require(nbits <= 32)?;
    require(self.bitpos + nbits as u64 <= self.data.len() as u64 * 8)?;
    let mut out: u32 = 0;
    for _ in 0..nbits {
      let byte = self.data[(self.bitpos >> 3) as usize];
      let bit = (byte >> (7 - (self.bitpos & 7))) & 1;
      out = (out << 1) | bit as u32;
      self.bitpos += 1;
    }
    Ok(out)
  }
}

struct NativeBits<'a> {
  data: &'a [u8],
  ptr: i64,
  cur: u64,
  bit: i32,
  words_left: i32,
  status: i32,
}

impl<'a> NativeBits<'a> {
  fn new(packet: &'a [u8], payload_offset: u32, byte_length: u32) -> Self {
    Self {
      data: packet,
      ptr: payload_offset as i64 - 8,
      cur: 0,
      bit: 0,
      words_left: ((((byte_length as i32) + 7) / 8) + 1) & !1,
      status: 0,
    }
  }

  fn load_next_word(&mut self) {
    self.words_left -= 1;
    if self.words_left < 0 {
      self.status = 2;
      return;
    }
    self.ptr += 8;
    let mut x: u64 = 0;
    for i in 0..8 {
      x <<= 8;
      let pos = self.ptr + i;
      if pos >= 0 && pos < self.data.len() as i64 {
        x |= self.data[pos as usize] as u64;
      }
    }
    self.cur = x;
    self.bit = 64;
  }

  fn read_bits(&mut self, nbits: i32) -> u32 {
    let mut out: u32 = 0;
    let mut remaining = nbits;
    while remaining > 0 {
      if self.bit <= 0 {
        self.load_next_word();
        if self.status != 0 {
          return if remaining >= 32 { 0 } else { out << remaining };
        }
      }
      let take = remaining.min(self.bit);
      self.bit -= take;
      let mask = if take >= 64 { u64::MAX } else { (1u64 << take) - 1 };
      let chunk = ((self.cur >> self.bit) & mask) as u32;
      out = if take >= 32 { chunk } else { (out << take) | chunk };
      remaining -= take;
    }
    out
  }

  fn read_unary_zeros_plus_one(&mut self) -> i32 {
    let mut zeros = 0;
    while self.status == 0 {
      let bit = self.read_bits(1);
      if self.status != 0 {
        break;
      }
      if bit != 0 {
        return zeros + 1;
      }
      zeros += 1;
    }
    zeros + 1
  }
}

fn update_width(br: &mut NativeBits, wstate: i32) -> i32 {
  if br.read_bits(1) == 0 || br.status != 0 {
    return wstate;
  }
  if br.read_bits(1) == 0 || br.status != 0 {
    return wstate + br.read_unary_zeros_plus_one();
  }
  for zeros in 0..(wstate - 1).max(0) {
    if br.read_bits(1) != 0 {
      return wstate - (zeros + 1);
    }
  }
  0
}

fn read_zero_run(br: &mut NativeBits, remaining: i32) -> i32 {
  if remaining <= 1 {
    return remaining;
  }
  let mut max_prefix = 0;
  let mut x = remaining - 1;
  while x != 0 {
    max_prefix += 1;
    x >>= 1;
  }
  let mut zeros = 0;
  while zeros < max_prefix {
    if br.read_bits(1) != 0 {
      break;
    }
    if br.status != 0 {
      return remaining;
    }
    zeros += 1;
  }
  if zeros >= max_prefix {
    return remaining;
  }
  let base = 1 << zeros;
  if base >= remaining {
    return remaining;
  }
  let extra = if zeros != 0 { br.read_bits(zeros) as i32 } else { 0 };
  (base + extra).min(remaining)
}

fn decode_coeff_group(br: &mut NativeBits, nbits: i32, shift: i32, vals: &mut [i32; 4]) {
  for v in vals.iter_mut() {
    let x = if nbits > 0 { br.read_bits(nbits) } else { 0 };
    let mut value = x as i32;
    if shift > 0 && x > 0 {
      value = (((2u64 * x as u64 + 1) << (shift - 1)).wrapping_sub(x as u64 & 1)) as i32;
    }
    *v = value;
  }
}

fn apply_signs(br: &mut NativeBits, vals: &mut [i32; 4]) {
  for v in vals.iter_mut() {
    if *v > 0 {
      let bit = br.read_bits(1) as i32;
      *v = v.wrapping_sub(v.wrapping_mul(2).wrapping_mul(bit));
    }
  }
}

fn decode_component(br: &mut NativeBits, groups: i32, shift: i32, dst: &mut [i32]) {
  let row_width = dst.len();
  let mut width_state = update_width(br, 0);
  let mut gi = 0;
  let mut out = 0usize;
  while gi < groups {
    if br.status != 0 || width_state > 0x13 {
      if br.status == 0 {
        br.status = 1;
      }
      dst[out..].fill(0);
      return;
    }
    if width_state == 0 {
      let run = read_zero_run(br, groups - gi);
      let zeros = (run as usize * 4).min(row_width - out);
      dst[out..out + zeros].fill(0);
      out += zeros;
      gi += run;
      if gi >= groups {
        break;
      }
      width_state = br.read_unary_zeros_plus_one();
      continue;
    }
    let mut vals = [0i32; 4];
    decode_coeff_group(br, width_state, shift, &mut vals);
    let next_width = if gi + 1 < groups { update_width(br, width_state) } else { width_state };
    apply_signs(br, &mut vals);
    for v in vals {
      if out < row_width {
        dst[out] = v;
        out += 1;
      }
    }
    width_state = next_width;
    gi += 1;
  }
  dst[out..].fill(0);
}

fn row_multiplier(group: i32) -> i32 {
  match group {
    4 => 8,
    0 => 1,
    g => 1 << (g - 1),
  }
}

fn infer_packet_width(group: i32, packet_type: i32, mosaic_width: i32) -> Res<i32> {
  require(mosaic_width > 0 && mosaic_width & 15 == 0)?;
  if packet_type == 1 {
    return Ok(if group == 4 { mosaic_width / 2 } else { mosaic_width / 16 });
  }
  if packet_type == 3 && (1..=3).contains(&group) {
    return Ok(mosaic_width / (1 << (5 - group)));
  }
  Err("ARW6: corrupt packet".to_string())
}

fn expected_packet_rows(group: i32, coded_height: i32) -> Res<i32> {
  require((0..=4).contains(&group))?;
  require(coded_height > 0 && coded_height <= 0x7fff)?;
  let padded_height = align_up(coded_height, 16);
  Ok((padded_height / 16 + 1) * row_multiplier(group))
}

fn parse_directory(stream: &[u8]) -> Res<Vec<DirectoryEntry>> {
  require(stream.len() >= 0x80)?;
  let stream_size = stream.len() as u64;
  let offs = [0usize, 3, 6, 9, 12];
  let mut group_lengths = [0u32; 5];
  for (g, length) in group_lengths.iter_mut().enumerate() {
    *length = (be32(stream, 0x10 + offs[g]) >> 4) & 0x0fff_fff0;
  }
  let mut entries = Vec::new();
  let mut pos = 0x30usize;
  let mut base: u64 = 0;
  for (group, &group_length) in group_lengths.iter().enumerate() {
    require(pos as u64 + 0x10 <= stream_size)?;
    let n_entries = (stream[pos] & 0x0f) as usize;
    require(n_entries <= 9)?;
    let mut values = [0u32; 9];
    for i in 0..5 {
      values[i] = (be32(stream, pos + offs[i]) & 0x00ff_ffff) << 4;
    }
    let mut consumed = 0x10;
    if n_entries >= 5 {
      require(pos as u64 + 0x20 <= stream_size)?;
      for i in 0..4 {
        values[5 + i] = (be32(stream, pos + 0x10 + offs[i]) & 0x00ff_ffff) << 4;
      }
      consumed = 0x20;
    }
    let mut local: u64 = 0;
    for (index, &length) in values.iter().enumerate().take(n_entries) {
      let start = 0x80 + base + local;
      require(start <= stream_size && length as u64 <= stream_size - start)?;
      entries.push(DirectoryEntry {
        group: group as i32,
        index: index as i32,
        start: start as u32,
        length,
      });
      local += length as u64;
    }
    require(local <= group_length as u64)?;
    base += group_length as u64;
    pos += consumed;
  }
  Ok(entries)
}

fn parse_packet(data: &[u8]) -> Res<Packet<'_>> {
  let length = data.len() as u64;
  require(length >= 16)?;
  let mut br = HeaderBits { data, bitpos: 0 };
  let control_count = br.read(16)?;
  let extra_count = br.read(24)?;
  let tag4 = br.read(4)?;
  let reserved4 = br.read(4)?;
  let type2 = br.read(2)?;
  let control_words = br.read(6)?;
  let block_count = br.read(16)?;
  let width_marker = br.read(8)?;
  let reserved8 = br.read(8)?;
  for _ in 0..5 {
    require(br.read(8)? == 0)?;
  }
  require(tag4 == 4 && reserved4 == 0 && control_words == 0)?;
  require(type2 == 1 || type2 == 3)?;
  require(block_count > 0 && block_count <= 30000)?;
  require(width_marker == 0x10 && reserved8 == 0)?;
  let control_bytes = (control_count as u64 + 1) << 4;
  let total_bytes = (control_count as u64 + 1 + extra_count as u64) << 4;
  require(total_bytes == length && control_bytes <= length)?;
  let mut cursor = control_bytes;
  let mut records = Vec::with_capacity(block_count as usize);
  for _ in 0..block_count {
    let byte_length = br.read(16)?;
    let mut selectors = [0u8; 3];
    for s in selectors.iter_mut().take(type2 as usize) {
      *s = br.read(4)? as u8;
    }
    require(byte_length as u64 <= length && cursor <= length - byte_length as u64)?;
    records.push(PacketRecord {
      byte_length,
      selectors,
      payload_offset: cursor as u32,
    });
    cursor += byte_length as u64;
  }
  require(cursor <= total_bytes)?;
  Ok(Packet {
    kind: type2 as i32,
    block_count: block_count as i32,
    data,
    records,
  })
}

fn decode_packet_arrays(stream: &[u8], dir: &[DirectoryEntry], mosaic_width: i32, coded_height: i32, group: i32, index: i32) -> Res<Vec<Plane>> {
  let e = dir
    .iter()
    .find(|e| e.group == group && e.index == index)
    .copied()
    .ok_or_else(|| "ARW6: missing packet".to_string())?;
  let p = parse_packet(&stream[e.start as usize..(e.start + e.length) as usize])?;
  let components = if p.kind == 1 { 1 } else { 3 };
  let row_width = infer_packet_width(group, p.kind, mosaic_width)?;
  let row_mult = row_multiplier(group);
  let rows = p.block_count * row_mult;
  let expected_rows = expected_packet_rows(group, coded_height)?;
  let groups_per_row = (row_width + 3) / 4;
  require(row_width > 0 && groups_per_row > 0 && rows > 0)?;
  if rows != expected_rows {
    require(coded_height & 15 != 0 && expected_rows - rows == row_mult)?;
  }
  require(p.block_count as u64 <= stream.len() as u64 / 16 + 1)?;
  let mut planes = (0..components).map(|_| Plane::new(expected_rows, row_width)).collect::<Res<Vec<_>>>()?;
  // Every record starts its own bit reader at its own payload offset, so
  // records decode independently (in parallel; same result as in order).
  let band = (row_mult * row_width) as usize;
  let mut bands: Vec<Vec<&mut [i32]>> = (0..p.block_count).map(|_| Vec::with_capacity(components)).collect();
  for plane in planes.iter_mut() {
    for (record, chunk) in bands.iter_mut().zip(plane.data.chunks_mut(band)) {
      record.push(chunk);
    }
  }
  bands.par_iter_mut().zip(p.records.par_iter()).for_each(|(record, rec)| {
    let mut bits = NativeBits::new(p.data, rec.payload_offset, rec.byte_length);
    for (ci, chunk) in record.iter_mut().enumerate() {
      let shift = if (ci as i32) < p.kind { rec.selectors[ci] as i32 } else { 0 };
      for dst in chunk.chunks_mut(row_width as usize) {
        if rec.byte_length == 0 {
          dst.fill(0);
        } else {
          decode_component(&mut bits, groups_per_row, shift, dst);
        }
      }
    }
  });
  drop(bands);
  Ok(planes)
}

fn integrate_type1(coeffs: &Plane, rows: i32) -> Res<Plane> {
  require(rows > 0 && rows <= coeffs.rows)?;
  let mut out = Plane::new(rows, coeffs.cols)?;
  for y in 0..rows {
    let mut acc = sign16(coeffs.at(y, 0)) * 2;
    out.set(y, 0, acc / 2);
    for x in 1..coeffs.cols {
      acc += sign16(coeffs.at(y, x)) * 2;
      out.set(y, x, acc / 2);
    }
  }
  Ok(out)
}

fn head_rows(src: &Plane, rows: i32) -> Res<Plane> {
  require(rows >= 0 && rows <= src.rows)?;
  let mut out = Plane::new(rows, src.cols)?;
  let n = rows as usize * src.cols as usize;
  out.data.copy_from_slice(&src.data[..n]);
  Ok(out)
}

fn skip_rows(src: &Plane, skip: i32) -> Res<Plane> {
  require(skip >= 0 && skip <= src.rows)?;
  let mut out = Plane::new(src.rows - skip, src.cols)?;
  let start = skip as usize * src.cols as usize;
  out.data.copy_from_slice(&src.data[start..]);
  Ok(out)
}

fn inv53_axis0(low: &Plane, high: &Plane) -> Res<Plane> {
  require(low.rows == high.rows && low.cols == high.cols)?;
  let mut lo2 = Plane::new(low.rows, low.cols)?;
  for y in 0..low.rows {
    for x in 0..low.cols {
      let hp = high.at(if y > 0 { y - 1 } else { 0 }, x) as i64;
      let hc = high.at(y, x) as i64;
      lo2.set(y, x, low.at(y, x) - floor_shift(hp + hc + 2, 2));
    }
  }
  let mut out = Plane::new(low.rows * 2, low.cols)?;
  for y in 0..low.rows {
    for x in 0..low.cols {
      let ln = lo2.at(if y + 1 < low.rows { y + 1 } else { y }, x) as i64;
      let hi2 = high.at(y, x) + floor_shift(lo2.at(y, x) as i64 + ln, 1);
      out.set(y * 2, x, lo2.at(y, x));
      out.set(y * 2 + 1, x, hi2);
    }
  }
  Ok(out)
}

fn inv53_axis1(low: &Plane, high: &Plane) -> Res<Plane> {
  require(low.rows == high.rows && low.cols == high.cols)?;
  let mut lo2 = Plane::new(low.rows, low.cols)?;
  for y in 0..low.rows {
    for x in 0..low.cols {
      let hp = high.at(y, if x > 0 { x - 1 } else { 0 }) as i64;
      let hc = high.at(y, x) as i64;
      lo2.set(y, x, low.at(y, x) - floor_shift(hp + hc + 2, 2));
    }
  }
  let mut out = Plane::new(low.rows, low.cols * 2)?;
  for y in 0..low.rows {
    for x in 0..low.cols {
      let ln = lo2.at(y, if x + 1 < low.cols { x + 1 } else { x }) as i64;
      let hi2 = high.at(y, x) + floor_shift(lo2.at(y, x) as i64 + ln, 1);
      out.set(y, x * 2, lo2.at(y, x));
      out.set(y, x * 2 + 1, hi2);
    }
  }
  Ok(out)
}

fn inv53_axis0_high_leading(low: &Plane, high: &Plane) -> Res<Plane> {
  require(low.cols == high.cols)?;
  require(high.rows == low.rows || high.rows == low.rows + 1)?;
  let mut lo2 = Plane::new(low.rows, low.cols)?;
  let mut hi2 = Plane::new(high.rows, high.cols)?;
  if high.rows == low.rows + 1 {
    for y in 0..low.rows {
      for x in 0..low.cols {
        lo2.set(y, x, low.at(y, x) - floor_shift(high.at(y, x) as i64 + high.at(y + 1, x) as i64 + 2, 2));
      }
    }
    for x in 0..high.cols {
      hi2.set(0, x, high.at(0, x) + lo2.at(0, x));
      hi2.set(high.rows - 1, x, high.at(high.rows - 1, x) + lo2.at(low.rows - 1, x));
    }
    for y in 1..high.rows - 1 {
      for x in 0..high.cols {
        hi2.set(y, x, high.at(y, x) + floor_shift(lo2.at(y - 1, x) as i64 + lo2.at(y, x) as i64, 1));
      }
    }
    let mut out = Plane::new(low.rows * 2 + 1, low.cols)?;
    for y in 0..low.rows {
      out.row_mut(y * 2).copy_from_slice(hi2.row(y));
      out.row_mut(y * 2 + 1).copy_from_slice(lo2.row(y));
    }
    let last = out.rows - 1;
    out.row_mut(last).copy_from_slice(hi2.row(hi2.rows - 1));
    return Ok(out);
  }
  for y in 0..low.rows {
    for x in 0..low.cols {
      let next_y = if y + 1 < high.rows { y + 1 } else { y };
      lo2.set(y, x, low.at(y, x) - floor_shift(high.at(y, x) as i64 + high.at(next_y, x) as i64 + 2, 2));
    }
  }
  for x in 0..high.cols {
    hi2.set(0, x, high.at(0, x) + lo2.at(0, x));
  }
  for y in 1..high.rows {
    for x in 0..high.cols {
      hi2.set(y, x, high.at(y, x) + floor_shift(lo2.at(y - 1, x) as i64 + lo2.at(y, x) as i64, 1));
    }
  }
  let mut out = Plane::new(low.rows * 2, low.cols)?;
  for y in 0..low.rows {
    out.row_mut(y * 2).copy_from_slice(hi2.row(y));
    out.row_mut(y * 2 + 1).copy_from_slice(lo2.row(y));
  }
  Ok(out)
}

fn synthesize_level(ll: &Plane, sub0: &Plane, sub1: &Plane, sub2: &Plane) -> Res<Plane> {
  let (h, w) = (ll.rows, ll.cols);
  require(sub0.cols == w && sub1.cols == w && sub2.cols == w)?;
  require(sub0.rows > h && sub1.rows > h && sub2.rows > h)?;
  let mut lh = Plane::new(h, w)?;
  let mut hh = Plane::new(h, w)?;
  for y in 0..h - 1 {
    for x in 0..w {
      lh.set(y, x, sub1.at(y + 1, x));
      hh.set(y, x, sub2.at(y + 1, x));
    }
  }
  for x in 0..w {
    lh.set(h - 1, x, sub0.at(h, x));
    hh.set(h - 1, x, sub1.at(h, x));
  }
  let low_horizontal = inv53_axis0(ll, &lh)?;
  let high_horizontal = inv53_axis0(&head_rows(sub0, h)?, &hh)?;
  inv53_axis1(&low_horizontal, &high_horizontal)
}

fn synthesize_guard_group1(ll: &Plane, sub0: &Plane, sub1: &Plane, sub2: &Plane) -> Res<Plane> {
  let (h, w) = (ll.rows, ll.cols);
  require(sub0.cols == w && sub1.cols == w && sub2.cols == w)?;
  require(sub0.rows >= h + 2 && sub1.rows >= h + 2 && sub2.rows >= h + 2)?;
  let mut lh = Plane::new(h + 1, w)?;
  let mut hh = Plane::new(h + 1, w)?;
  let mut hl = Plane::new(h, w)?;
  for y in 0..h {
    for x in 0..w {
      hl.set(y, x, sub0.at(y + 1, x));
      lh.set(y, x, sub1.at(y + 1, x));
      hh.set(y, x, sub2.at(y + 1, x));
    }
  }
  for x in 0..w {
    lh.set(h, x, sub0.at(h + 1, x));
    hh.set(h, x, sub1.at(h + 1, x));
  }
  let low_horizontal = inv53_axis0_high_leading(ll, &lh)?;
  let high_horizontal = inv53_axis0_high_leading(&hl, &hh)?;
  inv53_axis1(&low_horizontal, &high_horizontal)
}

fn synthesize_guard_group2(ll: &Plane, sub0: &Plane, sub1: &Plane, sub2: &Plane, odd_edge_mode: bool) -> Res<Plane> {
  let (h, w) = (ll.rows, ll.cols);
  require(sub0.cols == w && sub1.cols == w && sub2.cols == w)?;
  require(sub0.rows >= h + 3 && sub1.rows > h && sub2.rows > h)?;
  let mut hl = Plane::new(h, w)?;
  let mut lh = Plane::new(h, w)?;
  let mut hh = Plane::new(h, w)?;
  for x in 0..w {
    lh.set(0, x, sub0.at(0, x));
    hh.set(0, x, edge_detail(sub0.at(1, x), odd_edge_mode));
  }
  for y in 0..h {
    for x in 0..w {
      hl.set(y, x, sub0.at(y + 2, x));
    }
  }
  for y in 1..h {
    for x in 0..w {
      lh.set(y, x, sub1.at(y + 1, x));
      hh.set(y, x, sub2.at(y + 1, x));
    }
  }
  let low_horizontal = inv53_axis0_high_leading(ll, &lh)?;
  let high_horizontal = inv53_axis0_high_leading(&hl, &hh)?;
  inv53_axis1(&low_horizontal, &high_horizontal)
}

fn synthesize_guard_group3(ll: &Plane, sub0: &Plane, sub1: &Plane, sub2: &Plane, odd_edge_mode: bool) -> Res<Plane> {
  let (h, w) = (ll.rows, ll.cols);
  require(sub0.cols == w && sub1.cols == w && sub2.cols == w)?;
  require(sub0.rows >= h + 5 && sub1.rows >= h + 2 && sub2.rows >= h + 2)?;
  let mut hl = Plane::new(h, w)?;
  let mut lh = Plane::new(h, w)?;
  let mut hh = Plane::new(h, w)?;
  for x in 0..w {
    hl.set(0, x, sub0.at(0, x));
    lh.set(0, x, sub0.at(1, x));
    hh.set(0, x, edge_detail(sub0.at(2, x), odd_edge_mode));
    lh.set(h - 1, x, sub0.at(h + 3, x));
    hh.set(h - 1, x, edge_detail(sub0.at(h + 4, x), odd_edge_mode));
  }
  for y in 1..h {
    for x in 0..w {
      hl.set(y, x, sub0.at(y + 3, x));
    }
  }
  for y in 1..h - 1 {
    for x in 0..w {
      lh.set(y, x, sub1.at(y + 3, x));
      hh.set(y, x, sub2.at(y + 3, x));
    }
  }
  let low_horizontal = inv53_axis0(ll, &lh)?;
  let high_horizontal = inv53_axis0(&hl, &hh)?;
  inv53_axis1(&low_horizontal, &high_horizontal)
}

fn synthesize_level_stride(ll: &Plane, sub0: &Plane, sub1: &Plane, sub2: &Plane, edge_rows: i32, odd_edge_mode: bool) -> Res<Plane> {
  if edge_rows == 0 {
    return synthesize_level(ll, sub0, sub1, sub2);
  }
  let (h, w) = (ll.rows, ll.cols);
  require(sub0.cols == w && sub1.cols == w && sub2.cols == w)?;
  require(sub0.rows >= h + edge_rows * 2 && sub1.rows >= h + edge_rows && sub2.rows >= h)?;
  let mut hl = Plane::new(h, w)?;
  let mut lh = Plane::new(h, w)?;
  let mut hh = Plane::new(h, w)?;
  for y in 0..edge_rows {
    for x in 0..w {
      hl.set(y, x, sub0.at(y, x));
      lh.set(y, x, sub0.at(y + edge_rows, x));
      hh.set(y, x, edge_detail(sub1.at(y, x), odd_edge_mode));
    }
  }
  for y in edge_rows..h - edge_rows {
    for x in 0..w {
      hl.set(y, x, sub0.at(y + edge_rows, x));
      lh.set(y, x, sub1.at(y + edge_rows, x));
      hh.set(y, x, sub2.at(y + edge_rows, x));
    }
  }
  for y in h - edge_rows..h {
    let k = y - (h - edge_rows);
    for x in 0..w {
      hl.set(y, x, sub0.at(h + k, x));
      lh.set(y, x, sub0.at(h + edge_rows + k, x));
      hh.set(y, x, edge_detail(sub1.at(h + k, x), odd_edge_mode));
    }
  }
  let low_horizontal = inv53_axis0(ll, &lh)?;
  let high_horizontal = inv53_axis0(&hl, &hh)?;
  inv53_axis1(&low_horizontal, &high_horizontal)
}

fn final_green(ll: &Plane, detail: &Plane, top_rows: i32) -> Res<Plane> {
  let (h, w) = (ll.rows, ll.cols);
  require((0..=8).contains(&top_rows))?;
  require(detail.cols == w && detail.rows >= 8 + (h - top_rows).max(0))?;
  let mut selected = Plane::new(h, w)?;
  for y in 0..h {
    let src_y = if y < top_rows { y } else { y + 8 - top_rows };
    selected.row_mut(y).copy_from_slice(detail.row(src_y));
  }
  let mut odd_green = Plane::new(h, w)?;
  for y in 0..h {
    let prev_y = if y > 0 { y - 1 } else { y };
    for x in 0..w {
      let pred = if x + 1 < w {
        floor_shift(
          selected.at(y, x + 1) as i64 + selected.at(prev_y, x) as i64 + selected.at(y, x) as i64 + selected.at(prev_y, x + 1) as i64,
          2,
        )
      } else {
        floor_shift((selected.at(prev_y, x) as i64 + selected.at(y, x) as i64) * 2, 2)
      };
      odd_green.set(y, x, floor_shift(2 * ll.at(y, x) as i64 - pred as i64, 1));
    }
  }
  let mut even_green = Plane::new(h, w)?;
  for y in 0..h {
    let next_y = if y + 1 < h { y + 1 } else { y };
    even_green.set(
      y,
      0,
      selected.at(y, 0) + floor_shift((odd_green.at(y, 0) as i64 + odd_green.at(next_y, 0) as i64) * 2, 2),
    );
    for x in 1..w {
      let sum = odd_green.at(y, x - 1) as i64 + odd_green.at(next_y, x - 1) as i64 + odd_green.at(next_y, x) as i64 + odd_green.at(y, x) as i64;
      even_green.set(y, x, selected.at(y, x) + floor_shift(sum, 2));
    }
  }
  let mut out = Plane::new(h, w * 2)?;
  for y in 0..h {
    for x in 0..w {
      out.set(y, x * 2, even_green.at(y, x));
      out.set(y, x * 2 + 1, odd_green.at(y, x));
    }
  }
  Ok(out)
}

fn sample_from_signed(x: i32) -> u16 {
  lut_value((x + INTERNAL_BIAS).clamp(0, 4095))
}

fn clamp_signed_code(x: i32) -> i32 {
  (x + INTERNAL_BIAS).clamp(0, 4095) - INTERNAL_BIAS
}

struct DecodedTile {
  red_residual: Plane,
  blue_residual: Plane,
  full_green: Plane,
}

fn decode_stream_tile(stream: &[u8]) -> Res<DecodedTile> {
  let header = parse_stream_header(stream).ok_or_else(|| "ARW6: bad stream header".to_string())?;
  let dir = parse_directory(stream)?;
  let coded_height = header.logical_height;
  let width = header.coded_width;
  require(width > 0 && coded_height > 0)?;
  let padded_height = align_up(coded_height, 16);
  let guarded_height = coded_height != padded_height;
  let low_rows = padded_height / 16;
  let low_start = if guarded_height { 1 } else { 0 };
  let low_count = low_rows - low_start;

  let base_plane = |index: i32| -> Res<Plane> {
    let planes = decode_packet_arrays(stream, &dir, width, coded_height, 0, index)?;
    let plane = integrate_type1(&planes[0], low_start + low_count)?;
    if low_start != 0 { skip_rows(&plane, low_start) } else { Ok(plane) }
  };
  // The green plane and the two residuals are reconstructed independently.
  let chain = |index: i32, odd_last: bool| -> Res<Plane> {
    let mut plane = base_plane(index)?;
    for group in 1..=3 {
      let edge_rows = match group {
        1 => 0,
        2 => 1,
        _ => 2,
      };
      let odd = odd_last && group == 3;
      let p = decode_packet_arrays(stream, &dir, width, coded_height, group, index)?;
      plane = if guarded_height {
        match group {
          1 => synthesize_guard_group1(&plane, &p[0], &p[1], &p[2]),
          2 => synthesize_guard_group2(&plane, &p[0], &p[1], &p[2], false),
          _ => synthesize_guard_group3(&plane, &p[0], &p[1], &p[2], odd),
        }
      } else {
        synthesize_level_stride(&plane, &p[0], &p[1], &p[2], edge_rows, odd)
      }?;
    }
    Ok(plane)
  };
  let ((green, g4), (red_residual, blue_residual)) = rayon::join(
    || rayon::join(|| chain(0, false), || decode_packet_arrays(stream, &dir, width, coded_height, 4, 0)),
    || rayon::join(|| chain(1, true), || chain(2, true)),
  );
  let (green, g4, red_residual, blue_residual) = (green?, g4?, red_residual?, blue_residual?);

  let full_green = final_green(&green, &g4[0], if guarded_height { 2 } else { 4 })?;
  Ok(DecodedTile {
    red_residual,
    blue_residual,
    full_green,
  })
}

/// Decodes a Sony ARW 6 strip (TIFF compression 32766) of `width` x
/// `height` RGGB samples.
pub fn decode_sony_arw6(strip: &[u8], width: usize, height: usize) -> Res<PixU16> {
  require(width > 0 && height > 0 && width & 15 == 0 && height & 1 == 0)?;
  require(strip.len() >= (STREAM_OFFSET + 0x80) as usize && strip.len() <= 1 << 30)?;
  let streams = find_streams(strip, width as i32, height as i32);
  require(!streams.is_empty())?;
  for s in &streams {
    require(s.offset as u64 + s.length as u64 <= strip.len() as u64)?;
    require(s.tile_x >= 0 && s.tile_y >= 0 && (s.tile_x + s.tile_w) as usize <= width && (s.tile_y + s.tile_h) as usize <= height)?;
  }
  let tiles = streams
    .par_iter()
    .map(|s| decode_stream_tile(&strip[s.offset as usize..(s.offset + s.length) as usize]))
    .collect::<Res<Vec<_>>>()?;
  let mut out = vec![0u16; width * height];
  for (s, tile) in streams.iter().zip(&tiles) {
    let half_h = s.logical_height / 2;
    let half_w = s.coded_width / 2;
    require(tile.full_green.rows >= half_h && tile.full_green.cols == s.coded_width)?;
    require(tile.red_residual.rows >= half_h && tile.red_residual.cols == half_w)?;
    require(tile.blue_residual.rows >= half_h && tile.blue_residual.cols == half_w)?;
    for y in 0..half_h {
      let row0 = (s.tile_y + y * 2) as usize * width + s.tile_x as usize;
      let row1 = row0 + width;
      for x in 0..half_w {
        let g0 = clamp_signed_code(tile.full_green.at(y, x * 2));
        let g1 = clamp_signed_code(tile.full_green.at(y, x * 2 + 1));
        let gavg = floor_shift(g0 as i64 + g1 as i64, 1);
        let xo = (x * 2) as usize;
        out[row0 + xo] = sample_from_signed(gavg + 2 * tile.red_residual.at(y, x));
        out[row0 + xo + 1] = sample_from_signed(tile.full_green.at(y, x * 2 + 1));
        out[row1 + xo] = sample_from_signed(tile.full_green.at(y, x * 2));
        out[row1 + xo + 1] = sample_from_signed(gavg + 2 * tile.blue_residual.at(y, x));
      }
    }
  }
  Ok(PixU16::new_with(out, width, height))
}
